_PALM_DETAIL_EXCEL_JSON = r'''[{"category": "生命線", "id": 1, "name": "綺麗な生命線", "detail": "あなたの生命線は切れ目なく美しい線を描いています。\n抜群の生命力を持ち、思い通りに行動できる良い状態です。親指のつけ根にまで弧が長く流れていたら、「長寿」という生命力の証。病気とは無縁の健康な生活を送ることができます。疲れていても、少しでも休養をとればすぐに回復し、積極性と行動力を発揮できるはずです。健康であることを喜び、明るく暮らしていけば、ハッピーな未来を築いていけるはずです。100才を越す生命線であると、統計上証明されます。ご先祖様に感謝しましょう。"}, {"category": "生命線", "id": 2, "name": "大きくはみ出した生命線", "detail": "あなたの生命線は大きく弧を描いています。\nバイタリティにあふれ、何かを生み出す力に優れています。大きく描く弧が、中指の中心から手首に下ろした線より張り出している人は、エネルギッシュで強い影響力の持ち主。いつも元気で活発な人。持ち前のバイタリティで、まわりから注目を集めます。たくさんの子孫にも恵まれるでしょう。病気にも強く110才を越す生命線であると、統計上証明されています。"}, {"category": "生命線", "id": 3, "name": "旅行線（中）", "detail": "あなたの生命線は大きく切り替わっています。\n大きく線が切り替わっているのは、人生の途中で生き方が大きく変わるサイン。海外へ移住したり、都会暮らしから田舎暮らしになることなど、生活環境が大きく変わることを暗示しています。冒険心やフロンティア精神に富んだ人に現れやすい相です。"}, {"category": "生命線", "id": 4, "name": "内側に入る生命線", "detail": "あなたの生命線は弧のカーブがゆるいです。\n内向的で控えめ。小さな世界で満足する傾向があり、消極的で自己主張が苦手なタイプです。人の意見に左右されやすく、限られた世界で生きていきがちなので、もっと多くの人と関わるように努めていくと、人生を楽しもうという心のハリが出てきて、行動力もアップします。手を合わせることでご先祖様のお力をいただけます。"}, {"category": "生命線", "id": 5, "name": "二重生命線（濃）", "detail": "あなたの生命線は命線が2本あります。\n生命線が二重になっているのは、人の2倍バイタリティーがある人。体力抜群で、人の2倍動き回っても疲れることがなく、いつも元気いっぱいです。二人分の生命力があります。生命力が強いことをあらわします。\n事故などで奇跡的に助かった人にも多くみられます。長生きをすると思って良いでしょう。\nあなたも100歳前後まで生きる可能性が大きいでしょう。"}, {"category": "生命線", "id": 6, "name": "二重生命線（薄）", "detail": "あなたの生命線は命線が2本あります。タフネスな体育会系です。\n生命線が二重になっているのは、人の2倍バイタリティーがある人。体力抜群で、人の2倍動き回っても疲れることがなく、いつも元気いっぱいです。楽観的でさっぱりした性格で、嫌なことがあっても運動して汗を流せば忘れてしまいます。ストレスがたまらず、心も健康です。ただ自分の体力を過しすぎる傾向があり、無茶をして健康を害することもあるので注意してください。"}, {"category": "生命線", "id": 7, "name": "旅行線（火）", "detail": "あなたの生命線は月丘に注ぐ線があります。\n生命線から月丘に注ぐ長い線を「海外流出線」と呼びます。生まれ育った国だけではなく、地球上の広い範囲でダイナミックに活躍する人に多く現れます。途中から二重性命線になっている人は、母国と呼べる国を\n2つ持ったり、異なる2種類の仕事で成功していく可能性があります。外国で成功してる方もいます。"}, {"category": "生命線", "id": 8, "name": "旅行線（小）", "detail": "あなたの生命線は先端が大きく二股に分かれています。\n安定感のある人生を大きく切り開いていくタイプ。体力や行動力、取り巻く環境にも恵まれた豊かな人生を過ごせそう。しっかりした人生基盤を保ちながら、新たなる発展の可能性を暗示しています。勇気を持っていろいろなことに取り組んでいきましょう。"}, {"category": "生命線", "id": 9, "name": "向上線", "detail": "あなたの生命線は生命線から立ち上がる線があります。逆境にめげずに行動し成功をつかむでしょう。\n努力開運線と呼ばれ、、目標に向かって真面目にコツコツと、頑張る力を持っています。逆境にめげない強さを表します。生きていることを喜び、目標を持って努力していけば、年を重ねるごとに、自分の力で可能性を高め、運勢を強化させていけるでしょう。チャレンジ精神が旺盛で、困難な物事にも果敢に挑戦します。七転び八起きの精神で、生まれ持ったパワーの強さを活かしながら、最後に大成功を収めるでしょう。"}, {"category": "生命線", "id": 10, "name": "内側に入る生命線", "detail": "あなたの生命線は出発点が親指に近く、ハリがないようです。\n起点が親指に近く、弧にハリがなく弱々しい印象の生命線は、自信がない人に現れやすい相です。生まれつき虚弱体質で、体力や気力に欠ける傾向にありますが、そうだったとしても、たとえば体質改善をしようとか、できないことよりはできることを考えようとか、前向きな力がついてくると流れもたおやかに改善されます。"}, {"category": "生命線", "id": 11, "name": "晩年濃い生命線", "detail": "あなたの生命線は弱い流れが強くなります。\n出発点が弱いけれど、だんだん線が強くなる場合、若年期は虚弱体質であったとしても、徐々に体力や行動力が強化されていくことを暗示しています。逆に、強い生命線が下に進むほど弱くなるから、年を取るごとに弱くなっていくので、体質改善を心掛けたり、健康診断を欠かさないよう十分気をつけましょう。\nご先祖様に感謝をすると、大きな事故から守っていただけます。"}, {"category": "生命線", "id": 12, "name": "運命線に繋がる生命線", "detail": "短くても運命線につながる線があります。\n生命線の短い人は寿命も短いと誤解されることも多いようですが、生命線と運命線をつなぐバイパスのような線が現れていれば、大丈夫。社会に対して積極的に働きかけようとすることで、世の中の役に立っているという実感が持て、健康な人生を送っていけます。"}, {"category": "生命線", "id": 13, "name": "途切れ途切れの生命線", "detail": "あなたの生命線は線が切れ切れになっています。\n動力や基礎体力に欠け、アクシデントに弱いタイプ。チェーン状や切れ切れの生命線は、気の流れが停滞しやすくトラブルを回避しにくい相なのです。持続力や免疫力に支しく、病気や怪我をしがち。ネガティブな気持ちを捨て、ポリシーを持ち強く生きようと心掛けることが開運の第一歩となります。"}, {"category": "生命線", "id": 14, "name": "シマのある生命線", "detail": "あなたの生命線は生命線にチェーンや島があるようです。\nチェーンや島は、気の滞りを現しています。スムーズに流れていればエネルギーは滞りませんが、チェーンや島が目立つときは気の流れが停滞し、病気になりがち。もし、そういった手のひらからの合図を見つけたら、体からの告だと受け取って、体質改善を心掛けましょう。"}, {"category": "生命線", "id": 15, "name": "主線から離れた二重生命線", "detail": "あなたの生命線は2本副生命線が流れています。\n生命線の親指側7～8ミリを流れているのが副生命線です。体力や気力の弱点をカバーし、サポートしてくれるありがたい味方の線です。副生命線が見られる人は、免疫力や抵抗力が強く、病気やケガをしても、運しい回復力を持っているので安心です。何事にも積極的に取り組み、どんなときも明るく、困難に負けない力を持っています。病気の対する抵抗力も強いでしょう。あなたには、少なくとも100才以上です。長命です。"}, {"category": "生命線", "id": 16, "name": "影響線が生命線に到達している", "detail": "生命線に接する平行な線が2～3本）人気度の高いモテ相です。\n2～3本の影響線が生命線の近くに出ている人は、モテオーラの持ち主。女性の場合は美人が多く、同からも異性からも好かれます。男性の場合も、魅力ある人柄で、公私を問わず周囲の皆から注目される人事故などで奇跡的に助かった人にも多くみられます。長生きをすると思って良いでしょう。"}, {"category": "生命線", "id": 17, "name": "細かい出会い線がたくさんある", "detail": "あなたの生命線は縦・横の細かい線がたくさんあります。恋愛に深入りしない手相です。\n金星丘に細かい線がたくさんあり、格子状になっている人は、あっさりした恋愛をする傾向にあります。1人にのめりこんだり、深入りしません。金星丘全体にこの線が出ている人は、異性が自分をどうみているか、敏感にキャッチする能力の持ち主で、異性と接する仕事に向いてます。異性間でもよい友人関係を築けるタイプです。"}, {"category": "生命線", "id": 18, "name": "生命線そばに四角紋", "detail": "生命線の切れ目、線上、線のすぐ近くに四角があります。\nこの印は、災難にあっても九死に一生を得る手相です。生命の保護をする記号で大病をしないことを表します。\n体に異常があっても心配はありません。必ず、快方に向かいます。最悪の事態は免れます。統計学上100才の上をいきます。2本3本の生命線のある人はもっとも命運が強いのです。"}, {"category": "頭脳線", "id": 19, "name": "真横平均的な頭脳線", "detail": "あなたの頭脳線は手のひらの側面の中間に向かうようです。\n夢をみることと現実を直視することのバランス感覚がとても発達しています。常識的ではあっても面白みのない堅物にはなりません。頭脳線が長い人はゆっくりじっくりモノを考える力があるので、思慮深い。行動を起こす前に熟慮。周囲からの頼を勝ち得ることができるでしょう。"}, {"category": "頭脳線", "id": 20, "name": "平均的な思考時間（not KY線）", "detail": "あなたの頭脳線は生命線と接して出発しています。\nバランス感覚に優れた、常識的な人です。適度な慎重さと前向きな実行力を持っています。突飛な行動に出ることはなく、タイミングや周囲の状況を見計らって行動を起こすので、失敗が少なく確実な人生を切り拓いていけるでしょう。"}, {"category": "頭脳線", "id": 21, "name": "考えすぎて失敗する頭脳線", "detail": "あなたの頭脳線は生命線と長くくっついています。\nとことん考え抜いてから行動に移すタイプ。ただ、重なっている部分が長いほど、優柔不断な相となり、消極的で臆病なところが目立ってしまいます。反対にミスが絶対に許されない慎重さや確実さを必要とする仕事には、とても向いた相です。"}, {"category": "頭脳線", "id": 22, "name": "頭脳線と生命線が離れている。", "detail": "あなたの頭脳線は生命線から離れて出発しています。\n頭脳明晰で自由な行動派。行動力と決断力が抜群な人。考察力があり、画期的な発想で問題を解決できる人。学歴や肩書きで人を判断せず、実力主義を頂きます。自分の才能を鼻にかけることなく、他人の才能を尊重し、お互いの自由を尊重しながら、共に高めあうことができる人です。もともと持つ独創性に行動力が加わる活発なタイプ。女性の場合はおてんばといわれることも。特に頭脳線と生命線が5mm以上離れている人は決断力も備わり、周りがあっと驚くことをさらりとやってしまうタイプです。"}, {"category": "頭脳線", "id": 23, "name": "超KY線", "detail": "あなたの頭脳線は生命線から1cm以上離れています\n生命線と頭脳線が1cm以上離れている人は思いつきで行動に出る傾向があります。冒険心には恵まれているものの、深く考えず、直感で動くところがあり、状況をわきまえずに、思ったことをそのまま口に出してしまうこともあります。突拍子もないトラブルに巻きこまれがち。ちゃんと考えて行動する力がついてくると、頭脳線と生命線を結ぶ架け橋のような線が現れてきます。話を最後まで聞くことです。"}, {"category": "頭脳線", "id": 24, "name": "金運線とくっつく頭脳線", "detail": "あなたの頭脳線は先端が跳ね上がっています\n現実的で金銭面にも強く、商才のある人に現れることが多い相です。ロマンティックなことは苦手なのですが、商売上手で人の扱いには長けています。現実的な豊かさを追い求めていくことが得意なので、確実に財を築いていくことができるでしょう。"}, {"category": "頭脳線", "id": 25, "name": "平均的な長さの頭脳線", "detail": "あなたの頭脳線は平均的に薬指の下まで伸びています。\n安定志向が強く生真面目。常識を重んじ、中道を生きようとする人です。家庭と仕事という礎があればよしとし、冒険的なことには挑みにくいタイプ。人間関係は良好。足場が固まった後、新しいことに挑戦しようとする意欲や向学心が出てくれば、人生がもっと豊かになるでしょう。"}, {"category": "頭脳線", "id": 26, "name": "真横に伸びる頭脳線（薄）", "detail": "あなたの頭脳線は直線的で全体的に薄い頭脳線です。\n自分に自信が持てず、人の意見に振り回されがち。現実的な考え方をするものの迷いが多く、自己主張も苦手。ともすれば人間関係ではいいように扱われることも。周囲に惑わされず、心の声に耳を澄まし、自分で答えを出そうという前向きさがあれば強い線に育っていきます。"}, {"category": "頭脳線", "id": 27, "name": "途中から下向きの頭脳線", "detail": "あなたの頭脳線は直線で始まって途中から弧を描いています。\n自分の好きなことや趣味を極めて、それを仕事にしていく力があります。頭の回転も速く集中力も抜群。ロマンの世界を現実的な社会に表現していく能力があります。アイデアが豊富で、企画能力があります。クリエイターと呼ばれる人に多く見られるのが、この手相。感受性が鋭く、神秘的な能力があります。"}, {"category": "頭脳線", "id": 28, "name": "二重頭脳線（はっきり）", "detail": "あなたの頭脳線は二\n二重頭脳線があります\n思考力に優れ、多芸多才です。\n頭脳明晰で、1つの考えにとらわれない理解力を持っています。考え方は柔軟で、適応力も抜群。1つの分野を徹底的に追求するというよりも、2つの違った分野で同時に活躍できるマルチな能力の持ち主です。"}, {"category": "頭脳線", "id": 29, "name": "くっきり短い頭脳線", "detail": "あなたの頭脳線はくっきりしていて短い頭脳線です。\nハッキリしていて、わかりやすい性格。嘘をついても、すぐにバレてしまうタイプです。即断力があり、物事に臨機応変に対処する才能があります。ただ、やや短気で面倒なことが苦手。人を好き嫌いで二分してしまうところがあるため、交友関係や社会的視野が狭まる傾向もあるので注意を。"}, {"category": "頭脳線", "id": 30, "name": "短く下向きの頭脳線", "detail": "あなたの頭脳線は弧を描いているが短い頭脳線です。\nささやかなことに幸せや喜びを見つけられる人。流行に敏感でいろんなものに興味を示します。欲も裏もないので、皆に愛されていくでしょう。ロマンティストではあるけれど、現実的な部分もあるため、実りのない恋や無謀な夢は追わないタイプです。"}, {"category": "頭脳線", "id": 31, "name": "月丘に到達し下向き", "detail": "あなたの頭脳線は月丘の下まで長くを描いています。\n夢とロマンを現実的な仕事として追求していく人。芸術性とず知に優れ自分の感性を形にして社会に影響を与えていきます。また、そういう自分の才能を熟知していて、落ち着きとカリスマ性を感じさせる人でもあります。自身の作品を通じて人とのつながりを広げていくでしょう。"}, {"category": "頭脳線", "id": 32, "name": "生命線にくっつくほど下向き（海）", "detail": "あなたの頭脳線は力なく垂れ下がるように下降しています。\nたくさんの夢を抱きつつも、現実の厳しさに尻込みし、自分の世界にこもってしまいがちな人。やや暗い印象をあたえがちで、限られた人とだけ親密になるタイプ。趣味は趣味、仕事は仕事と割り切り、夢の世界に浸りすぎないことで、社会とのバランスが得られます。"}, {"category": "頭脳線", "id": 33, "name": "真横に一直線", "detail": "あなたの頭脳線は直機に一直線に伸びています。\n理想派のリアリストの手相です。頭脳線が水平方向へまっすぐ伸びる人は、クールな性格で、感情よりも理屈を重んじるタイプで感情に流されることがありません。人間的な気配りに欠けるところがありますが、仕事をバリバリこなす有能な人です。実利を追求すること長けているため、会社経営などに向いています。"}, {"category": "頭脳線", "id": 34, "name": "障害線に遮られている", "detail": "あなたの頭脳線は線の先が障害線で止まっています\n前進しようとする自分をネガティブな思考が邪魔してるみたい。取り組む前に起こりそうな問題を憂い、あきらめてしまう傾向がありませんか。どんな障害も思いや勢いが勝てば越えられるもの。周囲の励ましや応援を前向きにとらえ、問題に立ち向かう気を持ちましょう。"}, {"category": "頭脳線", "id": 35, "name": "二重頭脳線（普通）二股", "detail": "あなたの頭脳線は先端が二股に分かれています。\n現実的で、かつ精神的に柔軟な考え方ができる人です。客観的な判断力を持ち、企画力や分析力に長けているので、クリエイティブな仕事に向いています。才能があります。豊かなアイデアの力で仕事を進めていくことができるタイプでしょう。音楽や美術で才能を発揮。"}, {"category": "頭脳線", "id": 36, "name": "生命線にくっつくほど下向き（濃）", "detail": "あなたの頭脳線は生命線からゆるやかに下降しています。\n綿密な作業を正確にこなせる研究者や技術者肌の人です。哲学的で思索することを好み、気の合う人とだけ蜜な交流を持っていきます。ただ、アピールカが消極的すぎて、せっかくの成果や才能が埋もれてしまいがち。\nいつも物事を深く考えるタイプです。自分を引き立ててくれる人との出会いによって成功への道が開けます。"}, {"category": "感情線", "id": 37, "name": "人差し指に流れ着く", "detail": "人差し指に向かって流れる感情線です。\nユーモアの持ち主で皆に慕われる人格者。中指と人差し指の間まで安定した線がまれているのは、どんな問題も余裕を持って受け止められる証です。\nまた線の先端と指の付け根の空間は、心の窓でもあります。この窓が開いている人は心の風通しが良く喜怒哀楽に波がないのも特徴。おおらかな印象の持ち主です。"}, {"category": "感情線", "id": 38, "name": "終点が人差し指と中指の間", "detail": "円満な人間関係を築ける人です。\n感情線の終点が人差し指と中指の間に入っている人は、情が厚く、マジメで誠実な性格です。バランス感覚にすぐれていて、どんな職場でも良好な人間関係を築いていける才能の持ち主です。理想型。誠実で相手に尽くすタイプです。信じやすいので時としては注意が必要です。"}, {"category": "感情線", "id": 39, "name": "人差し指に辿り着く", "detail": "先端が人差し指に届く感情線です。\n人一倍情が厚い人です。人のために尽くすこのタイプの中でも感情線が長い人は、特に情が厚い人です。\n他人のことを自分のことのように心配し、親身になって相談に乗るタイプ。介護や医療関係の仕事に就くと、高く評価されるでしょう。ただし、人に尽くしすぎてお節介になりやすい点には注意を。ストレスをため込みやすいので自己管理には気をつけて。"}, {"category": "感情線", "id": 40, "name": "大味な面積の感情線", "detail": "指の付け根までの面積が広い感情線です。\n心の許容量が広く、器が大きい人に多い相です。小さなことにとらわれず、暖かい人です。誰とでもすぐ伸\n良くなれる気さくなタイプで好奇心が旺盛な社交型。おっとりした明るい印象を持ち、頑固なところはなく、おおらかな性格です。"}, {"category": "感情線", "id": 41, "name": "縮こまった面積の感情線", "detail": "指の付け根までの面積が狭い感情線です。\n人と打ち解けにくく、自分の殻の中に閉じこもってしまいがち。自分が興味のあることはいくらでも熱心にはなれますが、社会との交流を図っていくのが苦手かもしれませんね。オタクと呼ばれる人にこの相が多いようです。"}, {"category": "感情線", "id": 42, "name": "先端が二股三股", "detail": "先端が大きな二、三股の感情線です。\n何歳になっても若い感性で人生を満喫でき、フロンティア精神が旺盛で、挑戦を恐れない人。初めてもの場所でも人見知りせず、明るさと積極性で切り拓き、リーダー的存在になっていきます。面白いものをみつけるのが上手で、周囲の人を飽きさせない魅力を兼ね備えています。自分の感情を押し付けず、聞き上手でもあります。どんな人にもきめ細かい対応ができるタイプ。他人の気持ちを理解することができる優しい性格で、接客業や看護師、介護職などに向いています。"}, {"category": "感情線", "id": 43, "name": "下ひげが複数ある", "detail": "下降する波線が複数の感情線です。\n優しさと温和な人柄が外見からもにじみ出ています。2~3mmの下降線が規則正しく刻まれている人は、心のひだが多く、繊細な感性を持っているタイプです。思いやりと同情心に満ちているので、涙もろく傷つきやすい優しい心の持ち主。人間関係に疲れたら、動植物との触れ合いが完気の元になるでしょう。"}, {"category": "感情線", "id": 44, "name": "上ひげが複数ある", "detail": "感情線から上昇する線を持つています\n積極的な自信家。ダイナミックな印象を与える人に多い相です。いつもやる気にあふれていて、怖いもの知らず。青春ドラマに出てくるヒーローのような熱血リーダータイプです。なぜかこの相を持つ人は声が大きくて、声に出してよく笑います。"}, {"category": "感情線", "id": 45, "name": "二重感情線", "detail": "二重感情線があります。\nどんなことでもどーんと受け止められる、心がとてもタフな人。スケールの大きな出来事にも、安定感を持って対処していける強さがあります。社会的に高い地位を得て、世の中の重要なポジションにつくことが多いでしょう。本来、愛情が豊かな人ですが、二重感情線の持ち主は、さらに普通の人の2倍の愛情を持ち合わせて情熱的。なにごとにもパワフルに取り組み、周囲に深い愛情を注ぐことで開運。家庭に入ると、一家をリードしてたくましく支えます。"}, {"category": "感情線", "id": 46, "name": "下向きに下がる感情線", "detail": "波うって下降する感情線があります。\nささいなことでも動揺しやすく、感情の起伏が激しい人に現れやすい相。人から安心させてもらいたいという依存心が強く、ひっきりなしに相談をもちかけるなど、周囲を振り回して迷惑をかけてしまう可能性があります。まずは自分の心の声に耳を傾けてみて。"}, {"category": "感情線", "id": 47, "name": "途切れ途切れの感情線", "detail": "切れ切れに流れる感情線があります。\n短気でせっかち、忍耐力に欠け、イライラした印象を与えがちな人の相。いわゆるキレやすい人で、小さなことで怒りだしたり、暴力的になるトラブルメーカーの傾向があります。深呼吸を心掛け、ゆっくり考える癖をつけると線がつながっていきます。"}, {"category": "感情線", "id": 48, "name": "ぐちゃぐちゃな感情線", "detail": "ランダムな線でつながる感情線\n心に荒波が立ちやすく、トラブルメーカーになりやすい人です。気分にムラがあり興奮しやすく、独占欲や執着心が強いわりに飽きっぽく、周囲を振り回してしまいがち。人の話に耳を傾けるなど、ゆったりした生活を心掛けると感受性の強さがプラスに向かいった線になっていきます。"}, {"category": "感情線", "id": 49, "name": "鎖状の感情線", "detail": "チェーン状になっている感情線があります。\n感情や表情を表に出せなくて、暗い印象を持たれがち。考えすぎで、自己表現がうまくいかず、思いが周囲に伝わりにくいので、我慢や気遣いに疲れ果て、時折感情を大爆発させてしまう恐れがあります。また執着心も強く、他人を圧追してしまうことも。時には明るい歌でも歌って心の無りを吹き飛ばしましょう。"}, {"category": "特殊な線", "id": 50, "name": "マスカケ線", "detail": "いわゆるマスカケ相といわれる吉相で、感情線と頭脳線が一本につながっています）\nもともと一芸に秀でて\nいたり、特殊な専門分野で活躍したりする才能があります。肉体的にも感覚的にも優れた才能を持って生まれ、我が身一つで勝負して大きな人生を切り拓く力を持っています。さらにそれが感情線と頭脳線が合体したますかけ相になっていれば、歴史に名を残すような大きな成功を手にする可能性が。ただ、強情すぎる性格のため、周囲から孤立するなど協調性の有無で成功に差が生じます。平凡な人生を選択すると個性やエネルギーが強すぎて、周囲との関係に無理が生じやすくなってしまうかもしれません。"}, {"category": "感情線", "id": 51, "name": "マスカケ線+感情線", "detail": "感情線を伴うマスカケ線があります。\nマスカケ相に加え、感情線がある人は優れた感性・感覚を生かした分野で独立し、作家やアーティスト、クリエイターとして大成していく可能性を持っています。本名やアーティスト名が社会的にも浸透し、認められ、影響力を持つことになります。小さなころから非凡な才能を発揮しカリスマ性を有した人に刻まれる吉相です。"}, {"category": "運命線", "id": 52, "name": "手首から垂直に上がる", "detail": "手首から垂直に上がる運命線があります。個性や特技を生かし、自分の選んだ道を突き進む人。\n一見、典型的な運命線に見えますが、手首からまっすぐ立ち上がるのは珍しいケースです。自分の力で人生を切り拓き、自分らしい生き方をプロデュースしていく底力を持っています。\n個性が生きる職業に向いており、独立独歩の人生を歩む人に多く現れる線です。リーダーシップを発揮し\n第一線で活躍、運命線が長く終点が土星丘に届く人は、すぐれた統率力と実行力の持ち主。\n自己主張しながら周囲を引っぱっていくタイプで、どんどん出世していきます。女性の場合は、家庭に収まることなく社会の第一線で活躍していくでしょう。"}, {"category": "運命線", "id": 53, "name": "月丘から上がる", "detail": "斜めから立ち上がる運命線があります。\n生まれつき魅力的な才能を持ち、周囲からの引き立てを受けやすい人。チャンスと愛情を追い風に、能力を存分に発揮していきます。自分から動かずともスカウトや思いがけないチャンスを得て、能力を発揮。月丘から立ち上がっていれば、スター的な魅力で大衆に支持され、大きな成功を収めていく可能性を秘めています。"}, {"category": "運命線", "id": 54, "name": "途中から出環する", "detail": "高い位置から伸びる運命線があります。\n粘り強く頑張ることでいつしか成功していける人。手首から遠い位置に起点を持つ運命線は、大器晩成型のサイン。地道な努力を重ね、時間をかけて野望を確実に形にしていく力を持っています。遅咲きであっても後半の人生は堅実で充実したものに。手のひらの真ん中あたりならデビューは30歳くらいになります。"}, {"category": "運命線", "id": 55, "name": "途切れて重なりがある", "detail": "いったん大きく切り替わる運命線があります。\n転職や転地などで、大きな環境の変化が訪れるサインです。切り替わった先の線が濃いようなら、新たな生き方が充実して広がることを示唆しています。線が弱々しいなら、まだ変化のための準備が整っていないということ。目的意識を強く持って前向きに進めば、新しいフィールドでの活躍が期待できますよ。"}, {"category": "運命線", "id": 56, "name": "手首に「人」のような土台線がある", "detail": "運命線を支える土台線があります。\n常に現実を直視し、実力を高め、飛躍への努力を怠らない人。斜め下から運命線を支えるように立ち上がる\n”土台線”は、堅実な計画と努力によって目標を達成していく証です。幼い頃から達成願望が強く、実績を踏み台に、少しずつステップアップしていくのも特徴です。多くの勉強や体験が先の人生に生かされていきます。"}, {"category": "運命線", "id": 57, "name": "月丘から運命線に伸びる線がある", "detail": "パートナー線をともなう運命線があります。\n仕事の面でも頼し支え合っていく、良きパートナーの存在を表します。同じ目的意識を持って将来に向かうビジネスパートナーの可能性もありますが、多くの場合、夫や妻の協力を得て成功していくことを暗示しています。自分では職業を持っていなくても、知恵や運気を夫の仕事に与えている女性に現れることが多い線です。"}, {"category": "運命線", "id": 58, "name": "生命線から立ち上がる運命線", "detail": "生命線から立ち上がる運命線があります。\nオリジナリティあふれる個性や感性で世の中に影響を与え、成功する力を持った人。エネルギッシュな活動力の持ち主に現れる相です。生き方自体が仕事に結びつき、大きな影響力を世の中に及ぼして、周囲からの尊敬を集めることができます。"}, {"category": "運命線", "id": 59, "name": "生命線の内側から出発する運命線", "detail": "生命線の内側から出発する運命線があります。\n恵まれた家庭環境の中に生まれた人に多く現れる相で、別名・跡継ぎ相とも呼ばれます。先祖や親から代々続く職業や財産を受け継いで発展させていきます。昔から伝わる伝統的な職業や、いわゆる旧家の跡取りに多い相です。親兄弟の援助で運を開くタイプです。"}, {"category": "運命線", "id": 60, "name": "二重運命線", "detail": "2本で流れる運命線があります。\nメインになる活動を同時に2つ持ち、両方の世界で活躍していくことが可能なタイプ。例えばビジネスの世界で成功しながら、お金儲けとは関係ない趣味や研究の道でも成果を挙げていくなど、2つの大きな肩書で活躍する可能性があります。積極的に二足のわらじを履きこなしていきましょう。"}, {"category": "運命線", "id": 61, "name": "複数の運命線がある", "detail": "複数の運命線を持っています。\n一つの生き方、一つの肩書にとらわれず、いわゆる二足、三足のわらじを履いて生きていくタイプ。複数の肩書を持って世の中で活躍していくことが可能。幅広い分野で能力を発揮し、スケールの大きな生き方ができる、多才な人です。"}, {"category": "運命線", "id": 62, "name": "土台線の下から運命線", "detail": "土台線から出発運命線があります。\n木でたとえると、土台は根の部分。しっかり準備して、そこで培った力を持って世の中と関わっていきます。\n底力があるので、安定した人生を送れることでしょう。特殊な勉強や訓練を重ねたスペシャリストとして活躍する、将来が楽しみな人です。"}, {"category": "運命線", "id": 63, "name": "指側で分岐する運命線", "detail": "変化しながら上昇運命線があります。\n一つのことにとらわれず、世の中との関わり方を変えていける人ですが、その時どきで模索しながらより自分らしい生き方を追求し続けるタイプです。安定よりも自由を好み、さまざまな職業や環境を体験して、変化に富んだ人生を歩んでいきます。"}, {"category": "運命線", "id": 64, "name": "薄くて途切れ途切れ国標を見定める時期", "detail": "細かく薄く切れ切れ運命線があります。\n今はまだ、目標を見定める時期。流されやすく、自が持てない状況なので、親離れを拒んだり、他者に頼ったり、占いや神頼みに走ったり、依存心が強くなりがち。ただ、方向性が決まってないということは自由ということ。いろんな経験を積む時期ととらえ、目標を見つけていきましょう。"}, {"category": "運命線", "id": 65, "name": "薄くて目立たない自由時", "detail": "薄く目立たない運命線があります。\n将来に向かっての目標がまだ定まっていない時期かもしれません。このように運命線が薄く目立たないときは、自由時間と考えましょう。白いキャンパスに未来を描いていくのは自分自身。本当に何がやりたいのかはっきりしてくると、線もはっきりしてきますよ。"}, {"category": "運命線", "id": 66, "name": "薄くて複数ある運命線", "detail": "薄くても複数の運命線があります。\n華やかで目立つ仕事でなくても、地道に与えられてた役割をしっかり果たしていきます。人をサポートする力にも恵まれて、いわゆる縁の下の力持ちとして家族や身内のために尽くし、社会を支えていける人です。"}, {"category": "運命線", "id": 67, "name": "途中で止まる運命線", "detail": "途中で止まる運命線があります。\n何かが障害になって先に進まない状態。頭脳線で止まっているなら、考え方や知識に問題があって運命が伸び悩んでいる状況。感情線なら、性格面に、やや問題があるかも。欠点、弱点を認識して改善できれば、運命線は先に伸びていきます。"}, {"category": "太陽線", "id": 68, "name": "細かく複数ある", "detail": "細かく複数ある太陽線があります。\n常にハッピーな波動で、明るさを周囲に与え続ける人気者です。どこにいても、その場を楽しみ、楽しませる力がある人。持ち前の朗らかさで人を惹きつける、職場や学校の人気者になっていきます。どんな困難も前向きな姿勢で、明るく乗り越える力を持っているので、相談相手としても多くの人に慕われるでしょう。"}, {"category": "太陽線", "id": 69, "name": "くっきり伸び上がる", "detail": "くっきり伸び上がる太陽線があります。\n世の中に多大な影響を与えていく可能性を持ちます。事業で大成功したり、作品が人の心を揺さぶったりと、自分の名で成したことが人々に大きなインパクトを与えていきますので、この線の持ち主は自覚のある生活と覚悟が必要。線をせき止める横線がある場合は、思い上がると伸び悩むという未来への管告です。"}, {"category": "太陽線", "id": 70, "name": "2本くっきりある", "detail": "太陽線が2本くっきり現れています。\n2つの大きな仕事によって成功していく人。二兎追うものは一兎をも得ずということわざとはうらはらに、多才な活躍をする可能性を秘めています。音楽家でありながら文筆家といったように、本業と趣味の世界、両方で成功する才能の持ち主です。"}, {"category": "太陽線", "id": 71, "name": "上のほうに短くくっきり", "detail": "上の方に短くくっきり太陽線があります。\n今はまだ名もない小さな存在だと感じている人でも、薬指の近くに現れている太陽線があるならば、晩年になって充実感のある生き方をつかむことができるはずです。それまでに培ってきた人柄の良さで、周囲から尊敬される老後を迎えるでしょう。"}, {"category": "太陽線", "id": 72, "name": "指の中まで伸びている", "detail": "薬指の中まで伸び上がる太陽線があります。\n自分の寿命が尽きた後も功績や作品が長く世の中に影響を与え続けることを暗示しています。大きな会社の創設者になったり、なにかの創始者に多い相。多くの人に夢や気を与え、伝説化されるような偉業をなす人に現れる相です。"}, {"category": "太陽線", "id": 73, "name": "月丘から繋がる太陽線", "detail": "丘から立ち上がる太陽線があります。持久力があり、着実に財を築くタイプです。\n芸術的な感性や才能を生かして社会的成功を勝ち得ていきます。芸術家や表現者に現れてくる相で、作り出した作品は多くの人々の支持を集め、感動させるでしょう。ユニークな発想や表現手段、秀でた芸術的感性で社会に喜びを与えていける人です。"}, {"category": "太陽線", "id": 74, "name": "生命線から立ち上がる太陽線", "detail": "生命線から立ち上がる太陽線があります。文才があり、地道な努力で成功タイプです。\n人並み以上の努力や独自の才能で、大成功する可能性があります。自分のオリジナリティやキャラクターが直接大きな成功に結びついていく相です。右手にある場合は並外れた表現能力や根性で、左手ならば生まれ持った特別な環境や運命が味方となって、大きな財が与えられていくでしょう。"}, {"category": "太陽線", "id": 75, "name": "頭脳線から立ち上がる太陽線", "detail": "頭脳線から伸び上がる太陽線があります。\n斬新な発想や知力、判断力で皆に必要とされる人物。独自のアイデアや専門知識が多くの人の役に立つていきます。強い目的意識と聡明さを持ち、努力をいとわないのも特徴です。成功までに時間を必要とする仕事、例えば医師や弁護士などといった知的な職業で大成し、人々から必要とされる存在になるでしょう。"}, {"category": "太陽線", "id": 76, "name": "感情線から立ち上がる太陽線", "detail": "感情線から伸び上がる太陽線があります。\n心安らぐ笑いを振りまき、人々の心を和ませる、天然の可愛い魅力を持った人です。芸術的感性や生み出した作品、自身のキャラクターが人々に良い波動をもたらします。明るくサービス精神も旺盛で、人を笑わせることが大好き。そのエンターテイナー気質は、人々に自然な癒しを与えていくでしょう。"}, {"category": "太陽線", "id": 77, "name": "運命線から立ち上がる太陽線", "detail": "運命線から伸び上がる太陽線があります。\n自分が決めた道で、遅かれ早かれ結果を出していくことのできる人です。その人にとっての天職によって成功を収め、その成果が社会に良い影響を与えます。運命線と同じくらい強い線なら、働きに見合った評価がついてくると考えていいでしょう。運命線のどこに起点を持つかで成功の時期も推測することができます。"}, {"category": "太陽線", "id": 78, "name": "運命線と平行してくっきりと太陽線", "detail": "運命線と平行してくっきり現れる太陽線があります。\n自分の仕事を通して評価され、社会的成功を勝ち得ていくしるし。この線が2本強く現れていると、名誉も財も得られます。エネルギッシュに実力を発揮している人ならば、人望を得て、多くの人に影響を与えるのは然でしょう。"}, {"category": "太陽線", "id": 79, "name": "土台線（人）がある太陽線", "detail": "土台のある太陽線があります。\n長年の努力を重ねた結果、社会的に大きな働きや影響力を発揮する相。先が3つに分かれていれば、創業した会社が大発展したり、残した作品がさらに大きなムーブメントを起こすなど、後世にどんどん大きな影響力を放っていきます。"}, {"category": "太陽線", "id": 80, "name": "✕紋、シマを持つ", "detail": "✕印、島を持つ太陽線があります。\nよくないことで有名になるしるし。いわゆる悪名を馳せたり、スキャンダルの主人公になったり。✕印や島が出てきたら、少し謙虚になって、反省を。問題のもとになりそうな原因を見つめ、早めに解決していく必要があるでしょう。"}, {"category": "太陽線", "id": 81, "name": "＊紋、星紋を持つ", "detail": "＊印や星の形が現れています。\n太陽線に現れる*印や星印は、大成功して有名になる人に現れる特別な印です。スターと呼ばれる人にこの印がよく出ています。多くの人にとっての喜びの対象となる大吉相です。"}, {"category": "結婚線", "id": 82, "name": "感情線と小指の付け根の真ん中一本", "detail": "感情線と小指の付け根の真ん中に1本あります\nある程度社会経験を積んだ後に「この人だ」という相手に出会い結ばれる可能性があります。\nただ、本命いがいの恋は実りにくいかも。現在の恋人が運命の人だと思っているのに線が今の年齢よりも上にある場合は、結婚まで時間がかかると考えて、時期をまちましょう。"}, {"category": "結婚線", "id": 83, "name": "結婚線が一本真横", "detail": "1本の結婚線だけがまっすぐ真機へ伸びています\n運命のときにうんめいの人と出会える相です。生涯に一\n度だけの運命的な出会いを経て、結婚へつながっていきます。\nお互いがこの相なら理想的な結婚の可能性大。100%納得できるパートナーと堅実に人生を連れ添っていくことのできる相です。"}, {"category": "結婚線", "id": 84, "name": "小指の近くにある", "detail": "感情線と離れて、小指に近いところに結婚線があります\n小指に近いほどいわゆる晩婚の相です。線がはっきりしていれば、いつか必ず運命の人が現れます。\n結婚は早ければいいとゆうものではなく、人間的に成熟してから結婚するのも、一つのスタイルです。"}, {"category": "結婚線", "id": 85, "name": "感情線近くにある", "detail": "結婚線が感情線近くにくっきりと現れているます。結婚線が感情線に近いほど早婚の相。幼なじみや学生同士など、早い時期に人生のパートナーと出会い結婚が決まる可能性があります。\n線が薄いなら、出会っていても、結婚するかどうかはまだあやふや。二人の関係がどう育つのか、じっくり様子を見ていきましょう。"}, {"category": "結婚線", "id": 86, "name": "指に向かって上向き", "detail": "直線的な結婚線が弧を描いて上昇しています\nり。結婚によって精神的な自由や安心を経て、社会的に活躍\nする人です。エネルギーに満ちた人などで、家庭に押し込まれると力を持て余し、教育ママやパパになるなどマイナス作用もあるので気をつけましょう。結婚後も思う存分に仕事を続け、家庭は安らぎの場とするくらいが理想ですね。"}, {"category": "結婚線", "id": 87, "name": "手首側に下降", "detail": "結婚線が下降しています。\n結婚にたいする苦手意識やトラウマがある証。結婚してもネガテイブな思いが災いして破綻する可能性があります。恋人がいるなら、結婚を視野に入れない方が幸せに過ごせるかもしれません。結婚を望むなら、何に抵抗を感じているのかを自己分析して、克服する必要があるようです。"}, {"category": "結婚線", "id": 88, "name": "結婚線がくっきり2本", "detail": "同じくらい鮮やかな結婚線が2本はっきりと出ています。\n2度の結婚の可能性を暗示しています。一度の結婚だけでも、その前に運命的な出会いによる大恋愛を経験する可能性が。いずれは幸せに落ち着く相などでわかれを重くとらえすぎる必要はありません。運命の人が二人いるのだと考えてください。"}, {"category": "結婚線", "id": 89, "name": "薄い線が数本", "detail": "結婚線が数本あるが、どれも薄くてはっきりしていません。\nまだ結婚を真剣に望んでいなくて、恋愛を楽しみたい時期です。結婚までにいくつもの恋愛遍歴を重ねていく可能性があります。もし結婚を考えている相手がいたとしても、まだその時期ではないように感じます。"}, {"category": "結婚線", "id": 90, "name": "短く上向き", "detail": "極端に短く、上向きの結婚線があります。\n何かと白黒つけたがるタイプ。結婚できない相手には見向きもしないで、確実に結婚できる相手を探します\n・せっかちなので早婚になりやすい傾向があります。結婚後、嫉妬深さや独占欲の」強さに、相手が疲れてしまう恐れもあるので、結婚だけをゴールと思わず、愛を育む余裕を持ちましょう。"}, {"category": "結婚線", "id": 91, "name": "手の甲側が二股に", "detail": "出発点が離れた2本の線がつながっています。\n年齢差、親の反対、距離、国籍等々、さまざまな問題を克服し、幸せな結婚をしていく相。時間を重ねるごとにお互いへの理解を深めていけるタイプです。つながった線の先端がきれいに伸びているなら、現在、なんらかの障害があったとしても、焦らず二人の愛を育てていくことを心掛けましょう。"}, {"category": "結婚線", "id": 92, "name": "障害線で分断されている", "detail": "まっすぐな結婚線を障害線が分断しています\n縁は強いものの、生活を共にすると急裂や豚擦が生じやすいという暗示です。結婚相手を、性格ではなく条件で決めてしまうと、その危険性は大きくなっていきます。\n現在、仲が良くても、結婚するとすれ違いやケンカがふえる予感も。共に暮らすには我慢や譲歩も必要だと学ぶべきでしょう。"}, {"category": "結婚線", "id": 93, "name": "手の甲とヒラ側両方枝分かれ", "detail": "出発点と先端が2つに分かれています。\n「この人じゃないかも」と疑間を抱きながら結婚し、やっぱり違ったと離婚してしまう暗示。現在の恋人と結婚を考えていて、もし周囲からの反対や不安材料が\nあるならば、それらを解消してから決断しましょう。準備不足での結婚は破綻のもとになりがちです。"}, {"category": "結婚線", "id": 94, "name": "手のひら側が二股", "detail": "線の先端が二股に分かれています。\n最初は盛り上がるものの、生活を共にすると次第に冷める・・・という結婚を暗示しています。こころが離れたまま寂しい結婚生活や同棲を続けるより、前向きな別居を選んだほうがお互いのためかもしれません。同棲中なら一度解消することも選択肢の一つです。"}, {"category": "結婚線", "id": 95, "name": "複数ある結婚線の一本が濃い", "detail": "複数ある結婚線のうち1本が濃いです。\nいくつかの大恋愛を経て、幸せな結婚をするサイン。結婚線の数は婚姻の数ではなく、結婚に値するような恋愛の数と考えて。濃い線のある年齢に達していない場合は、結婚にとらわれず、訪れたれ恋愛を謳歌しましょう。"}, {"category": "結婚線", "id": 96, "name": "結婚線が手首に下向き", "detail": "下降する結婚線が複数刻まれています。\n性格上の父点を自覚しすぎているため結婚に踏み切れないタイプ。好きな人がいても「別れたとき、つらすぎる」などと考えが先走り、怖じ気づいてしまう傾向が。\n結果、二番手止まりに。最初から無理だとか決め付けず、簡単に」諦めないことが結婚への自を養う第一歩。"}, {"category": "結婚線", "id": 97, "name": "先端がどれも手首に下降枝分かれ", "detail": "先端がどれも下降し枝毛のような波線が出ています\n結婚に対して悲観的になったり、不安やイライラなどネガテイブな感情が出ている時期。そうした感情を抑圧して結婚すべきではありません。自分が結婚に何を望んでいるか見つめなおす時期にあります。"}, {"category": "結婚線", "id": 98, "name": "枝分かれの線の小指側上に綺麗な結婚線", "detail": "離婚を示す線の上にもう1本の鮮やかな結婚線があります。\n感情線に近いほうの結婚線が下降していたり薄いなど離婚の相が出ていても、上の線が鮮やかではっきりしているのなら、2度目の結婚で幸せが得られる可能性大。結婚を迷っているのなら、少し冷静に様子をみましょう。"}, {"category": "結婚線", "id": 99, "name": "結婚線がぐちゃぐちゃ", "detail": "結婚線の先端が房状に分かれています。\n早い時期に結婚の意味を見出せなくなり、結婚を破綻させるタイプ。冷め切っているのに、経済的な理由で別れない・・・という人も。\n「結婚は契約」と割り切るなら子供を作らないほうが賢明。現在、恋愛中でも心の底では結婚は望んでいないのでは？"}, {"category": "結婚線", "id": 100, "name": "線が薄く、先端の縦線でとまっている", "detail": "線が薄く、先端が立てに入る線で止まっています。\nまだ婚期にきてないのか、結婚を前向きに考えられない状況。親の反対、距離難、失業など外的要因や自信のなさがその原因。いずれにせよ、結婚には時期早々と考えて。心と環境の」準備が整えば縦の線は薄くなり、意欲的に結婚を喜べる状態になっていきます。"}, {"category": "結婚線", "id": 101, "name": "結婚線から上向きの短い線が複数本", "detail": "結婚線から上向きの短い線が複数本あります。\n愛する人を引っ張っていく力はあるものの、せっかちな性格と強い物言いで相手を消耗させる傾向があります。\n結婚後は相手の言い分には耳を貸さないなどという身勝手さで、両方の運気を下げてしまいそう。パートナ一は癒しや安らぎをもとめているものだと心得て。"}, {"category": "結婚線", "id": 102, "name": "結婚線の下に細かく並行する線", "detail": "結婚線の下に細かく並行する線があります。\n結婚線の1mmくらい下に細く並行して流れる線が現れている場合は、結婚相手もしくはステディに、別の相手がかって存在したか、もしくは存在している可能性が暗示されるという三角関係の相。相手がバツイチで再婚の場合も、こうした相となります。"}, {"category": "結婚線", "id": 103, "name": "1本の結婚線が弧を描いて下降し、感情線とクロス", "detail": "1本の結婚線が弧を描いて下降し、感情線とクロスしています。\n生涯添い遂げて、愛するパートナーを天に見送ってから、自分の人生をまっとうするという相です。この相が現れてきたら、それだけ尽くすことができる運命の人との出会いがあると考えましょう。"}, {"category": "結婚線", "id": 104, "name": "財運線に届く結婚線", "detail": "財運線に届く結婚線があります\n結婚によってお金や財産の縁が強くなっていく相です。豊かな財産を持つ結婚相手と結ばれたり、夫婦協力していくことで財を築いていったりということを暗示しています。結婚前の社会経験が、財を管理し殖やしていくことにつながる場合もあります。"}, {"category": "特殊な線", "id": 105, "name": "向上線", "detail": "生命線から垂直に1～2mmの長さで生命線に沿って立ち上がる線で、数本が等間隔で現れるのが特徴です。\nこの線がある人は、いつも目の前に目標を設定し、確実に達成していく努力家の証。日々のたゆまぬ努力を重ねていけるタイプ。小さな目標でもクリアしていくことで自分に対する頼が生まれていきます。\n努力できる自分、達成感を喜べる自分が、何よりも自分にとっての大切な味方となっていきます。\n実際に行動していくことでも刻み込まれていく線です。逆境にめげずにチャレンジ精神が旺盛で、困難な物事にも果敢に挑戦し成功をつかむ人です。"}, {"category": "特殊な線", "id": 106, "name": "仏眼（ぶつがん）", "detail": "親指の第一関節の内側に、目のような形で現れるのが仏紋です。\nこの相を持つ人は強い集中力と目指すものを達成させていこうという、ある種の念力にも恵まれています。この目の形は1つでクッキリ現れることが多いのですが、まれに唇のように2つ重なり合って出ている人もいます。\nダブルの仏心紋を持つ人は、一つの道にこだわらず2つの夢を同時に叶えていく力をもちます。\nいわゆる二足のわらじで成功していくタイプです。霊感が強く、勘の鋭い人にあらわれます。先祖を敬う心を持ち続けると、運が開けます。仏心を見つけたら年齢に関係なく、目標に向かって邁進していってください。"}, {"category": "特殊な線", "id": 107, "name": "旅行線", "detail": "生命線の流れの先から、手首の中央部分に向けて、斜めに流れているのが旅行線です。\nたいてい2-3本で現れてきます。旅のチャンスに多く恵まれ、旅から得た体験や知識に」「よって見聞を広げ、人生がより広く活性化していくことを暗示しています。\n新しい可能性が開けてくるはずです。遠方への旅だけにこだわらず、知らない路地や公園を散歩したり、屋上から夕日を眺めることも、素敵な旅心の実践となります。"}, {"category": "特殊な線", "id": 108, "name": "人気線", "detail": "丘の下、手首の横から2本並んで薬指の方向に斜めに立ち上がる流れが、人気線です。\nこの線を持つ人は生まれつき可愛らしい魅力を持ち、多くの人たちに可愛がられて育ちます。人気線のある人は普通の暮らしの中でも多くのチャンスが訪れやすく、多くの人たちが応援の手を差し伸べてくれたり、才能を見抜かれてスカウトされたりと、早い時期から注目を浴びる存在となっていきます。転生の魅力が刻み込まれた、非常に羨ましい相です。"}, {"category": "特殊な線", "id": 109, "name": "旅行線", "detail": "生命線から月丘の下部に向かって、斜めに長く流れていくのが海外流出線です。\n生まれ育った国や環境の範囲を越えて、広く国外のも活動の場所を得ようとする、国際感覚を持った人に現れます。国際結婚をする人のも現れてきます。幼い頃から、外国に対する憧れが強かったり、海外の文化や音楽、民族性の違いや外国語に興味を持つ人、国際結婚をする人にも現れやすい線でもあります。"}, {"category": "特殊な線", "id": 110, "name": "ユーモア線", "detail": "感情線の小指の下のあたりから、薬指に向かうような短く2本並んで斜めに昇ってくるのがユーモア線です\n。人を笑わせたり楽しませることが大好きな、笑いのセンス豊かな人によくみられます。ユーモアとは、ゆとりのある心からあふれてくる明るい知性があります。自分自身が物事を楽しむ力を持ち、その喜びを多くの人たちに分け与えられる素敵な人です。温かな笑顔やチャーミングな仕草や楽しい話術となって場を盛り上げ、多くの笑顔を生み出していくでしょう。この線を持つ人は、みんなの人気者になります。"}, {"category": "特殊な線", "id": 111, "name": "指導線", "detail": "出発点は何処であっても人差し指に向かって上昇していくのが指導線です。\n常に向上心をもって前向きに\n努力をする人に現れやすく、強いリーダーシップを発揮して、人の上に立ち、影響力を持つ優れた指導者としての活躍を暗示します。頭脳線から出発するなら、知恵や知識や、アイデアや計画を通して人の上に立つていく人です。感情線から出発するなら、そ人が持つ優しさや真心を伝え、借頼を得て多くの人々に慕われる人となっていきます。"}, {"category": "頭脳線", "id": 123, "name": "二重頭脳線（平行2本）", "detail": "あなたの頭脳線は同じ濃さの線が並行して流れています\n何事も器用にこなす才能の持ち主。心にも態度にも余裕のある人です。品があり、才能をひけらかさないので、\n人間関係も良好。2つの大きな夢を持ちますが、どちらかを諦めるとバランスを崩してしまうので、両方の道で活躍することを求めるべきでしょう。"}, {"category": "頭脳線", "id": 124, "name": "二重頭脳線、（真横分かれ）二股", "detail": "あなたの生命線は直線的な頭脳線が二股になっています。\n明るく聡明。男女問わず友達が多く、皆に愛される人です。客観的で広い視野の持ち主なので、渦の中にいても冷静で的確な答えを出すことができます。将来への展望もクリア。アイデアマンで冴えた意見が言えるため\n相談相手としても慕われます。"}, {"category": "頭脳線", "id": 125, "name": "二重頭脳線（枝分かれ下向き）下カーブ", "detail": "あなたの頭脳線は二股の先が急カーブを描いています\nその場の空気を瞬時に読み、自分の雰囲気を自在に変えることができる人。好育心旺盛で、お洒落や流行にも\nとても敏感。興味の幅がとても広く、人を飽きさせない雑学王のような人です。交友関係はバラエティに富み国際的な友好関係を築く人もいます。"}, {"category": "頭脳線", "id": 126, "name": "KY線", "detail": "あなたの頭脳線は生命線と離れて出発しています。\n自由な価値観を持つマイペース型。何かのスペシャリストとなり、集団には属さず、一匹狼として生きるタイプです。チャレンジ精神が旺盛で、行動力も抜群。個性を尊重する人と、特に気が合うでしょう。\n東縛の強い環境には身を置かず、我が道を進んでいきます。"}, {"category": "頭脳線", "id": 127, "name": "二重頭脳線（小）二股小", "detail": "あなたの頭脳線は先端が小さく二股に開いています\n身の回りのことを客観的に見つめ、分析する力のある人。細やかな気遣いや目配りができ、周囲から重宝がられます。しかし、心の奥では自分を変えたい、世界を広げたいと思っている部分も。日常レベルの小さな挑戦から始めてみましょう。"}, {"category": "特殊な線", "id": 128, "name": "金星帯", "detail": "センス抜群のファッションリーダー\n金星帯が出ている人は、抜群のセンスの良さを持っています。オシャレで流行にも敏感なので、ファッション関係やマスコミ関係などセンスを問われる仕事に就くと大活躍できるでしょう。また、感受性が鋭く、美的センスに恵まれます。創作能力があり、芸術家としての素質もあり。もともと文才があるため、趣味で詩や文章を書くと人々に認められ成功します。この線はセレクトショップのオーナーにも多い相です。会社員なら広報や営業職などに向いています。"}, {"category": "特殊な線", "id": 129, "name": "金星帯（はっきり）", "detail": "芸術家に向いている手相です。\n金星環がはっきり出ている人は、特に感受性がするどく、美に対する意識が強いことを示します。アーティストに多くみられる相なので、現在売出し中という人も自信を持って。独自の感性を持ち、美的センスにすぐれています。これは空想力が旺盛で、絵本作家やファンタジー作家に多い相。\nまた、異性に対して関心の高い、恋愛体質でもあります。"}, {"category": "特殊な線", "id": 130, "name": "細かくぐちゃぐちゃ", "detail": "手相全体に細かい横線があります。気の使いすぎで疲労ぎみ生命線の内側から出る細かい横線は「気疲れ線」といい、気を使いすぎて疲れているときに現れます。細かいことによく気づき、コミュニケーション能力も高いのですが、繊細すぎて疲れてしまうようです。特に横線が生命線を横切っている人は、ストレスをため\nやすいのでリラックスを心がけてください。"}, {"category": "特殊な線", "id": 10083, "name": "神秘十字線", "detail": "あなたの手のひらの（+）の印は神税（+）字形できわめて信仰心の深い人です。あなたのように\nはっきりと輝いているのは貴方の仰による仏性が深まったのです。祖先の喜びが見えるようです。\nあなたにも霊界にも花が咲誇っております 又直感力や予知能力など神秘的能力がある人でもあります。\nあなたのこれからの人生は祖先の助けや守護によってきわめて安楽に過ごせます。\n貴方の天命「110才」を貴方はまっとうして行くでしょう。長命です。ご先祖様より守られています。"}, {"category": "運命線", "id": 10150, "name": "秀吉", "detail": "あなたの運命線は、手首より中指に向かって昇っております。太さんにもあった線で、天下線ともいいます。一代で成功した人に必ずある線です。あなたにも成功者としての運命がそなわっております。あなたの成功は、ひたむきな努力により達成します。人よりの援助は期待できません。数々の障害を自分の力で排除しつつ昇っていかなくてはなりません。例え人の非難を受けることがあっても、自を持って我が道を進むことです。人の保証をせず、金も貸さず、何かをしてやれば人をしてくれると思うことはあなたの場合マイナスです。目標に向かって脇目もふらず、ひたむきに進むことにより確実に大成します。"}, {"category": "特殊な線", "id": 10153, "name": "ラッキーM", "detail": "あなたは、30才ごろより65歳ごろまでの人生で一番働きざかりに運命線があります。\nこのような運命線の形を『ラッキーのM』と名づけて幸運線の持ち主とします。感情線の形は、性質穏やかで協調性があり、あなたの成功は組織の中でより確実です。太陽線が安定しておりますあせらないことです。足元をもう一度見直して、足を踏みしめるようにして進むことです。あなたのような手相の人は、保証人関係で人生をしくじる人が最も多いですから徹底的に断ることです。そのことで気まずくなったり進みが止まっても一時的なことです。人生は長い目で見るものが勝ちです。"}, {"category": "特殊な線", "id": 10252, "name": "ソロモン環", "detail": "人差し指の基の木星丘に昇る縦の線、向上線は向上を願って働く努力家であります。あなたに向上線があります。願いが実現します。木星丘を斜めにカーブする線もあります。ソロモン線です。栄華を極めたソロモン王に刻まれていたのでソロモン線と呼びます。この線のある人はソロモン王のような栄華が可能であるといわれます。この線が明るく明瞭に輝いていれば夢の実現をじましょう。何事を起す\nとすれば向上線があるかないかで事を起こすか見送るかの判断にするとすれば貴方の向上線は事を始めれば望みがかない願いが実現良し。"}, {"category": "特殊な線", "id": 10299, "name": "三きもん", "detail": "あなたの手相は億万長者の形です。運命線と財運線と太陽線が3本三方伸びております。\n先祖よりの得を多く授かっております。このような手相の持ち主は努力せずとも大成します。人に対して情けを忘れず自分の心を裏切らず先祖の祭司を欠かさず、自分の運勢が別格であることの自を日常の生活に生かせばたくさんの人の上に立ちます。尊敬される人になります。トップになります。男女に関係なく億万長者になれます。それが早いか遅いかはあなたの生活の心構えによります。努力するしないは関係ありません。"}]'''

import re

# Excel由来の詳細DBを読み込む（JSONファイルがあれば優先）
import os as _os
_THIS_DIR = _os.path.dirname(_os.path.abspath(__file__))
_json_path = _os.path.join(_THIS_DIR, "tesou_detail_db_ja.json")
try:
    if _os.path.exists(_json_path):
        with open(_json_path, "r", encoding="utf-8") as _f:
            PALM_DETAIL_EXCEL = _json.load(_f)
    else:
        PALM_DETAIL_EXCEL = _json.loads(_PALM_DETAIL_EXCEL_JSON)
except Exception:
    PALM_DETAIL_EXCEL = _json.loads(_PALM_DETAIL_EXCEL_JSON)


# id(int) -> {category, id, name, detail}
PALM_DETAIL_BY_ID = {}
# category -> [(id, name), ...]
PALM_DETAIL_INDEX_BY_CATEGORY = {}
# 正規化した名称 -> [id, ...]（曖昧一致の補助）
PALM_DETAIL_IDS_BY_NORMNAME = {}

def _norm_palm_name(s: str) -> str:
    """ゆるい正規化：全角/半角・括弧内の読みを落として、記号/空白を除去"""
    if s is None:
        return ""
    s = str(s)
    # 括弧内の読み(例: 仏眼（ぶつがん）)を除去
    s = re.sub(r"[\(（].*?[\)）]", "", s)
    # 記号/空白を除去
    s = re.sub(r"[\s・\-‐ー―—_\./\\]", "", s)
    return s

for _row in PALM_DETAIL_EXCEL:
    try:
        _id = int(_row.get("id"))
    except Exception:
        continue
    _category = str(_row.get("category", ""))
    _name = str(_row.get("name", ""))
    _detail = str(_row.get("detail", ""))
    PALM_DETAIL_BY_ID[_id] = {"category": _category, "id": _id, "name": _name, "detail": _detail}
    PALM_DETAIL_INDEX_BY_CATEGORY.setdefault(_category, []).append((_id, _name))
    _nn = _norm_palm_name(_name)
    if _nn:
        PALM_DETAIL_IDS_BY_NORMNAME.setdefault(_nn, []).append(_id)

# 安定した順序にする
for _cat, _lst in PALM_DETAIL_INDEX_BY_CATEGORY.items():
    PALM_DETAIL_INDEX_BY_CATEGORY[_cat] = sorted(_lst, key=lambda x: x[0])

def find_palm_detail_ids_by_name(name: str):
    """名称から詳細DBのID候補を返す（完全一致→正規化一致）"""
    if not name:
        return []
    # 完全一致
    exact = [i for i, row in PALM_DETAIL_BY_ID.items() if row.get("name") == name]
    if exact:
        return sorted(exact)
    nn = _norm_palm_name(name)
    return sorted(PALM_DETAIL_IDS_BY_NORMNAME.get(nn, []))

def get_palm_detail_text_by_id(detail_id: int) -> str:
    """IDから詳細本文を返す（なければ空文字）"""
    try:
        detail_id = int(detail_id)
    except Exception:
        return ""
    row = PALM_DETAIL_BY_ID.get(detail_id)
    return row.get("detail", "") if row else ""


